import type { PagePackage, Values } from '../../../lib/low-code/schema'

/** 旧包仅兼容 main；多个表单不会被猜测、合并为节点配置。 */
export function resolveSettingsFormId(page: PagePackage): string {
    const explicit = page.extensions?.workflow?.settingsFormId
    if (explicit) return explicit
    const forms = new Set(
        Object.values(page.logic?.fields ?? {}).map(
            (field) => field.formId ?? 'main'
        )
    )
    if (forms.size && !forms.has('main'))
        throw new Error('配置页面需要明确绑定 settingsFormId')
    return 'main'
}

/** 与历史运行器一致：缺省表单为 main，缺省字段名为其逻辑 ID。 */
export function settingsFields(page: PagePackage, formId: string) {
    return Object.entries(page.logic?.fields ?? {})
        .filter(([, field]) => (field.formId ?? 'main') === formId)
        .map(([id, field]) => ({ ...field, id, name: field.name ?? id }))
}

export function jsonValues(value: Readonly<Record<string, unknown>>): Values {
    return JSON.parse(JSON.stringify(value)) as Values
}
